      expect(short, 'ok');
      final huge = JsAppErrorChannel.capExcerpt(
        'x' * (JsAppErrorChannel.maxMessageChars * 20),
      );
      expect(huge, contains('[truncated]'));
      expect(
        huge.length,
        lessThanOrEqualTo(JsAppErrorChannel.maxMessageChars + 16),
      );
    },
  );
}

