            line.indexOf('__wrapCb') < 0 &&
            line.indexOf('__faFingerprint') < 0) {
          frame = line;
          break;
        }
      }
      frame = frame.replace(/:[0-9]+:[0-9]+/g, '').replace(/[ \t\r\n]+/g, ' ').trim();
